import { Component } from '@angular/core';
import { JobService } from 'src/app/service/job/job.service';
import { Job } from '../../models/job';
import { Company } from 'src/app/landing/models/company';
import { CompanyService } from 'src/app/service/company/company.service';

@Component({
  selector: 'app-landing',
  templateUrl: './landing.component.html',
  styleUrls: ['./landing.component.css']
})
export class LandingComponent {

  constructor(
    private jobService: JobService,
    private compService: CompanyService
  ) {}

  jobs: Job[] = [];
  companies: Company[] = [];

  isLoggedIn = false;
  initials = 'U';
  profileRoute = '/';

  ngOnInit() {

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');

      if (role === 'COMPANY') {

        this.profileRoute = '/company-dashboard';

        const companyName = localStorage.getItem('companyName');

        if (companyName) {
          this.initials = companyName
            .split(' ')
            .map(x => x[0])
            .join('')
            .substring(0, 2)
            .toUpperCase();
        }

      } else {

        this.profileRoute = '/jobseeker-dashboard';

        const userName = localStorage.getItem('userName');

        if (userName) {
          this.initials = userName
            .split(' ')
            .map(x => x[0])
            .join('')
            .substring(0, 2)
            .toUpperCase();
        }
      }
    }

    this.getAllJobs();
    this.getAllCompanies();
  }

  getAllJobs() {
    this.jobService.getAllJobs().subscribe((res) => {
      this.jobs = res;
    });
  }

  getAllCompanies() {
    this.compService.getAllCompanies().subscribe((res) => {
      this.companies = res;
    });
  }

}
